/* SGI audiosa.app RC7 — protótipo autocontido, 100% fictício, sem fetch, Supabase nem autenticação real. */
import {DEMO_DATE,demoPatients,demoProfessionals,demoServices,demoAccounts,demoCards,demoTransactions,demoInventory,demoAppointments,demoHR,demoDocuments} from './mock-data.js';
const copy=x=>JSON.parse(JSON.stringify(x));
const state={app:'home',page:'resumo',role:'simone',theme:'light',search:'',filter:'all',step:1,
 patients:copy(demoPatients),people:copy(demoProfessionals),services:copy(demoServices),accounts:copy(demoAccounts),cards:copy(demoCards),tx:copy(demoTransactions),inventory:copy(demoInventory),appointments:copy(demoAppointments),hr:copy(demoHR),documents:copy(demoDocuments),
 obligations:[],recurring:[],stone:[],plans:[],notices:[{id:'AV-01',title:'Bem-vindo ao Laboratório de demonstração',body:'Todas as informações exibidas são fictícias. Nenhuma ação altera o sistema da clínica.',scope:'Todos',date:DEMO_DATE}],messages:[],intakes:[],transfers:[],catalog:[],tasks:[],audit:[],draft:null};
const modules=[{id:'finance',name:'Financeiro BI',icon:'▥',note:'Completo para demonstração local de cálculos e fluxos',phase:'Operação demonstrativa'},{id:'patients',name:'Atendimento e Pacientes',icon:'♧',note:'Cadastro, fila, check-in e prontuário sintético',phase:'Expansão simulada'},{id:'agenda',name:'Agenda',icon:'▦',note:'Agendamentos, encaixes, mensagens e atrasos',phase:'Expansão simulada'},{id:'documents',name:'Documentos e Termos AASI',icon:'▤',note:'Modelos, termos, versões e prévias não assinadas',phase:'Expansão simulada'},{id:'stock',name:'Estoque e AASI',icon:'◈',note:'Rastreio por série, teste, consignação e assistência',phase:'Expansão simulada'},{id:'gov',name:'Cadastro e Governança',icon:'◇',note:'Pessoas, vínculos, catálogo e solicitações',phase:'Expansão simulada'},{id:'hr',name:'RH e Colaboradores',icon:'♧',note:'Protocolos, férias, documentos e terceirização',phase:'Expansão simulada'}];
const menus={finance:[['resumo','Resumo Financeiro'],['lancamentos','Lançamentos'],['novo','Novo lançamento'],['compromissos','Compromissos'],['stone','Cartões e Stone'],['repasses','Repasses'],['convenios','Convênios'],['relatorios','Histórico e Relatórios'],['config','Configurações']],patients:[['cadastro','Pacientes'],['fila','Fila e Atendimento'],['prontuario','Prontuário sintético']],agenda:[['calendario','Calendário'],['comunicacoes','Comunicações']],documents:[['biblioteca','Biblioteca'],['termos','Termos AASI']],stock:[['inventario','Inventário'],['movimentos','Movimentações'],['insumos','Insumos']],gov:[['pessoas','Pessoas e vínculos'],['permissoes','Acessos e solicitações'],['catalogo','Catálogo Mestre']],hr:[['minhaarea','Minha Área'],['protocolos','Gestão de RH']]};
const defaults={finance:'resumo',patients:'cadastro',agenda:'calendario',documents:'biblioteca',stock:'inventario',gov:'pessoas',hr:'minhaarea'};
const profileNames={simone:'Dra. Simone · Direção',analista:'Analista · Financeiro',recepcao:'Recepção · Simulação',profissional:'Profissional · Simulação',rh:'RH · Simulação'};
const $=sel=>document.querySelector(sel); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(c)||0)/100);const moneyInput=s=>{let x=String(s??'').trim().replace(/[^\d,.-]/g,'');if(!x)return 0;return Math.round((x.includes(',')?Number(x.replace(/\./g,'').replace(',','.')):Number(x))*100)||0};
const pct=s=>{let n=Number(String(s||'').replace(',','.'));return Number.isFinite(n)?n:null};
const dateBR=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const person=id=>state.patients.find(p=>p.id===id)?.name||'—',prof=id=>state.people.find(p=>p.id===id)?.name||'—';
const uid=prefix=>prefix+'-'+Date.now().toString(36).slice(-6).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
const note=(msg,cls='')=>`<div class="notice ${cls}"><span>ⓘ</span><span>${msg}</span></div>`;
const badge=(s)=>{const css=/liquidado|conciliad|disponivel|aprovad|confirmad|conclu/i.test(s)?'ok':/rejeitad|erro|vencid|cancelad|divergenc/i.test(s)?'danger':/pendente|rascunho|previst|aguardando|teste|conferencia|análise|analise/i.test(s)?'warn':'';return `<span class="badge ${css}">${esc(s)}</span>`};
const btn=(text,action,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-act="${esc(action)}" ${extra}>${text}</button>`;
const head=(eyebrow,title,desc,actions='')=>`<header class="intro"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></header>`;
const box=(title,inner,sub='')=>`<section class="card"><div class="cardheader"><div><h2>${title}</h2>${sub?`<p class="tiny">${sub}</p>`:''}</div></div>${inner}</section>`;
const stat=(label,v,foot='',cls='')=>`<div class="card stat ${cls}"><div class="label">${label}</div><div class="value">${brl(v)}</div><small>${foot}</small></div>`;
const field=(label,name,type='text',value='',extra='',hint='')=>`<div class="field"><label for="f-${esc(name)}">${label}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}>${hint?`<span class="help">${hint}</span>`:''}</div>`;
const options=(arr,selected='')=>arr.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(l)}</option>`).join('');
const select=(label,name,arr,selected='',hint='')=>`<div class="field"><label for="f-${esc(name)}">${label}</label><select name="${esc(name)}" id="f-${esc(name)}">${options(arr,selected)}</select>${hint?`<small class="help">${hint}</small>`:''}</div>`;
const textArea=(label,name,value='',hint='')=>`<div class="field full"><label for="f-${esc(name)}">${label}</label><textarea id="f-${esc(name)}" name="${esc(name)}">${esc(value)}</textarea>${hint?`<small class="help">${hint}</small>`:''}</div>`;
const appOptions=state.accounts.map(a=>[a.id,`${a.name} (${a.kind.toUpperCase()})`]),patientOptions=[['','Sem paciente/Não se aplica'],...state.patients.map(a=>[a.id,a.name])],profOptions=[['','Não se aplica'],...state.people.map(a=>[a.id,a.name])],serviceOptions=[['','Outro / não se aplica'],...state.services.map(a=>[a.id,a.name])];
const table=(headers,rows)=>`<div class="tablewrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">Nenhum registro para os filtros atuais.</div></td></tr>`}</tbody></table></div>`;
function toast(t){const el=$('#toast');el.textContent=t;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3800)}
function audit(message){state.audit.unshift({id:uid('DEMO'),at:new Date().toLocaleString('pt-BR'),who:profileNames[state.role],message});}
function safeFinanceAccess(){return state.role!=='recepcao'&&state.role!=='profissional'&&state.role!=='rh'}
function permissions(){return state.role==='simone'}
function go(app,page){state.app=app;state.page=page||defaults[app]||'';state.filter='all';state.step=1;state.search='';render();window.scrollTo({top:0})}
function render(){document.documentElement.dataset.theme=state.theme;let nav=state.app==='home'?[]:menus[state.app]||[];if(state.app==='finance'&&!safeFinanceAccess())nav=[['lancamentos','Meus lançamentos'],['novo','Novo lançamento']];let showNav=state.app!=='home';const common=`<div class="topbar"><div class="brand"><div class="brandmark">A</div><div><b>SGI audiosa.app</b><small>Clínica Áudio S.A. · Protótipo RC7</small></div></div><div class="topactions"><span class="badge dark desktop-only">DEMO · SEM BANCO</span><select id="role" aria-label="Simular perfil" title="Troca de perfil é apenas simulação">${options(Object.entries(profileNames),state.role)}</select><button class="btn small" data-act="theme" title="Alternar tema">${state.theme==='light'?'☾':'☀'}</button><button class="btn small" data-act="notices" title="Avisos e tarefas">🔔</button>${showNav?btn('← Área de Trabalho','home','small'):''}</div></div>`;
const navHTML=showNav?`<aside class="sidebar"><h4>${esc(modules.find(m=>m.id===state.app)?.name||'SGI')}</h4>${nav.map(([id,name])=>`<button class="navbtn ${state.page===id?'active':''}" data-act="nav:${id}"><span class="nav-ic">${state.page===id?'▰':'◇'}</span>${esc(name)}</button>`).join('')}<h4>RETORNO</h4><button class="navbtn" data-act="home">⌂ &nbsp;Área de Trabalho</button><p style="padding:12px;font-size:11px;color:#b4d3db">Demonstração: nenhuma informação é enviada para a clínica, bancos, pacientes ou fornecedores.</p></aside>`:'';
let content='';try{content=state.app==='home'?launcher():state.app==='finance'?financeView():state.app==='patients'?patientView():state.app==='agenda'?agendaView():state.app==='documents'?documentsView():state.app==='stock'?stockView():state.app==='gov'?govView():state.app==='hr'?hrView():launcher()}catch(err){console.error(err);content=note('Falha no desenho da tela demonstrativa: '+esc(err.message),'danger')}
$('#root').innerHTML=`<div class="shell">${common}<div class="layout">${navHTML}<main class="content ${showNav?'':'launch-content'}" id="main">${content}<footer class="foot">SGI audiosa.app · RC7 demonstração sintética · Sem autenticação, banco, envio externo, assinatura válida ou operações reais. Os módulos futuros estão acessíveis somente para avaliação.</footer></main></div>${showNav?`<div class="mobile-nav"><button data-act="home"><span>⌂</span>Início</button><button class="${state.page===nav[0]?.[0]?'current':''}" data-act="nav:${nav[0]?.[0]||'resumo'}"><span>▤</span>${esc(nav[0]?.[1]||'Resumo')}</button><button data-act="mobile-menu"><span>☷</span>Mais</button><button data-act="notices"><span>♢</span>Avisos</button></div>`:''}</div>`;}
function launcher(){return `<div class="hero"><span class="badge">ÁREA DE TRABALHO ACOLHEDORA · OPÇÃO 3</span><h2>Gestão integrada, sem complicar a rotina.</h2><p>Explore todos os sete aplicativos em uma apresentação interativa. Financeiro BI tem fluxos demonstrativos de cálculos e lançamentos; os demais mostram situações fictícias e não operam dados reais.</p><div class="row">${btn('Abrir Financeiro BI','open:finance','primary')}${btn('Ver avisos','notices')}</div></div>`+head('Seu ambiente de trabalho','Aplicativos do SGI','Visualização de catálogo completo APENAS nesta demonstração. A versão operacional mostrará exclusivamente módulos contratados e autorizados.')+`<div class="grid">${modules.map(m=>`<button type="button" class="module c4" data-act="open:${m.id}"><span class="symbol">${m.icon}</span><h3>${m.name}</h3><p>${m.note}</p><span class="bottom">${m.phase} · Abrir →</span></button>`).join('')}</div>`+note('Perfis na barra superior são SIMULAÇÕES de experiência e não autenticação. Não insira CPF, nomes de pacientes reais, contratos, extratos ou qualquer dado privado nesta página pública.')+box('Comunicados demonstrativos',state.notices.slice(0,3).map(a=>`<div class="task"><div class="detail"><b>${esc(a.title)}</b><p>${esc(a.body)} · Público: ${esc(a.scope)}</p></div>${badge('aviso')}</div>`).join('')+`<div class="row">${btn('Abrir todos os avisos','notices')}${permissions()?btn('Publicar aviso fictício','modal:notice'):''}</div>`)}
function clinicCash(){return state.accounts.filter(a=>a.kind!=='personal').reduce((sum,a)=>sum+a.opening+state.tx.filter(t=>t.status==='liquidado'&&t.account===a.id).reduce((x,t)=>x+(t.kind==='entrada'?t.net:t.kind==='saida'?-t.net:0),0)+state.transfers.reduce((x,t)=>x+(t.to===a.id?t.value:0)-(t.from===a.id?t.value:0),0),0)}
function financialTotals(){let x=state.tx.filter(t=>t.status==='liquidado'&&state.accounts.find(a=>a.id===t.account)?.kind!=='personal');let income=x.filter(t=>t.kind==='entrada').reduce((s,t)=>s+t.net,0),expense=x.filter(t=>t.kind==='saida').reduce((s,t)=>s+t.net,0);let pendingIncome=state.tx.filter(t=>t.status==='previsto'&&t.kind==='entrada').reduce((s,t)=>s+t.net,0);let pendingOut=state.tx.filter(t=>t.status==='previsto'&&t.kind==='saida').reduce((s,t)=>s+t.net,0)+state.obligations.filter(o=>o.status==='previsto').reduce((s,o)=>s+o.value,0);return {income,expense,cash:clinicCash(),pendingIncome,pendingOut,net:income-expense}}
function reportRows(){return state.tx.map(t=>({data:t.date,tipo:t.kind,descricao:t.desc,bruto:brl(t.gross),taxas:brl(t.fees||0),liquido:brl(t.net),situacao:t.status,conta:state.accounts.find(a=>a.id===t.account)?.name||'Manual',paciente:person(t.patient),profissional:prof(t.professional)}))}
function financeView(){if(!safeFinanceAccess()&&!['lancamentos','novo'].includes(state.page))return renderReception();switch(state.page){case'resumo':return renderFinanceOverview();case'lancamentos':return renderTransactions();case'novo':return renderNewFinance();case'compromissos':return renderObligations();case'stone':return renderStone();case'repasses':return renderRepasses();case'convenios':return renderPlans();case'relatorios':return renderReports();case'config':return renderSettings();default:return renderFinanceOverview()}}
function renderFinanceOverview(){const t=financialTotals();return head('M1 / FINANCEIRO BI','Resumo Financeiro','Gestão executiva demonstrativa: caixa realizado, projeções e DRE gerencial são conceitos diferentes.',btn('＋ Novo lançamento','nav:novo','primary')+btn('Exportar Excel','export:xlsx'))+note('Valores sintéticos e gráficos demonstrativos. DRE gerencial não representa demonstração contábil homologada.')+`<div class="grid">${stat('Saldo de caixa demonstrativo',t.cash,'Contas da clínica, sem PF', 'c4 featured')}${stat('Fluxo previsto líquido',t.pendingIncome-t.pendingOut,'A receber menos a pagar', 'c4')}${stat('Resultado gerencial simplificado',t.net,'Recebido - pago; não é DRE contábil','c4')}${stat('Entradas liquidadas',t.income,'Créditos efetivos demonstrativos','c3')}${stat('Saídas liquidadas',t.expense,'Débitos efetivos demonstrativos','c3')}${stat('A receber',t.pendingIncome,'Não integra o caixa','c3')}${stat('A pagar',t.pendingOut,'Não integra o caixa','c3')}</div>`+`<div class="grid" style="margin-top:14px"><div class="c8">${box('Evolução financeira ilustrativa',`<div class="mini-plot">${[55,71,64,90,80,68].map((v,i)=>`<div class="bar"><i style="height:${v}%"></i><i style="height:${Math.round(v*.48+(i%2)*8)}%"></i></div>`).join('')}</div><div class="plot-labels">${['Jun','Jul','Ago','Set','Out','Nov'].map(s=>`<span>${s}</span>`).join('')}</div><p class="tiny">Gráfico histórico sintético; a fonte real dependerá da integração de dados.</p>`,'Legenda: turquesa entradas · azul despesas')}</div><div class="c4">${box('Próximas ações',`<div class="task"><div class="detail"><b>${state.tx.filter(t=>t.status==='aguardando validacao').length} solicitações para validar</b><p>Inicialmente apenas a Dra. Simone aprova solicitações da Recepção.</p></div></div><div class="task"><div class="detail"><b>${state.obligations.filter(x=>x.status==='previsto').length} parcelas em aberto</b><p>Baixa exige confirmação financeira.</p></div></div>${btn('Ver lançamentos','nav:lancamentos','primary')}${btn('Ver Stone','nav:stone')}`)}</div></div>`}
function renderReception(){return renderTransactions()}
function renderTransactions(){const reception=!safeFinanceAccess();const rows=state.tx.filter(t=>!reception||t.owner==='recepcao'||t.status==='aguardando validacao').slice().reverse().map(t=>`<tr><td><b>${esc(t.desc)}</b><div class="tiny">${esc(t.id)} · ${dateBR(t.date)}</div></td><td>${t.kind==='entrada'?'Entrada':'Saída'}</td><td>${brl(t.net)}</td><td>${badge(t.status)}</td><td>${esc(state.accounts.find(a=>a.id===t.account)?.name||'Origem não classificada')}</td><td><div class="cell-actions">${t.status==='aguardando validacao'&&permissions()?btn('Aprovar','approve:'+t.id,'small'):''}${t.status==='previsto'&&permissions()?btn('Liquidar','settle:'+t.id,'small'):''}${btn('Detalhar','detail:'+t.id,'small')}</div></td></tr>`);return head('FINANCEIRO / LANÇAMENTOS',reception?'Meus lançamentos e solicitações':'Lançamentos financeiros',reception?'Preparar → enviar para Dra. Simone → acompanhar; sem acesso a caixa global ou DRE.':'Entradas, saídas, previsões e aprovações, com estados separados da liquidação.',btn('＋ Novo lançamento','nav:novo','primary'))+(reception?`<div class="grid">${[['Novo lançamento','nav:novo','＋'],['Ler comprovante','modal:ocr','▧'],['Meus rascunhos','nav:lancamentos','▤'],['Enviados para validação','nav:lancamentos','◷']].map(([t,a,i])=>`<button class="module c3" data-act="${a}"><span class="symbol">${i}</span><h3>${t}</h3></button>`).join('')}</div>`:'')+`<div style="margin-top:18px">${box('Histórico operacional',table(['Lançamento','Tipo','Valor','Estado','Origem','Ações'],rows),'Aprovação de lançamento não prova pagamento.')}</div>`}
function renderNewFinance(){const d=state.draft||{kind:'saida',value:'',account:'cx-pj',method:'pix',date:DEMO_DATE,due:DEMO_DATE,desc:'',patient:'',professional:'',service:'',other:'',notes:'',installments:'1',first:DEMO_DATE,interest:'0'};const accountOptions=[...appOptions,['manual','Outra origem — classificar manualmente']];const main=`<form id="finance-entry"><input type="hidden" name="kind" value="${esc(d.kind)}"><div class="steps">${['1 · Operação','2 · Pagamento/Origem','3 · Conferir e registrar'].map((s,i)=>`<span class="step ${state.step===i+1?'current':''}">${s}</span>`).join('')}</div>${state.step===1?`<div class="fields">${select('Tipo de operação','operation',[['saida','Saída / despesa'],['entrada','Entrada / receita'],['transferencia','Transferência entre contas']],d.kind)}${field('Descrição / finalidade','desc','text',d.desc,'required maxlength="150"')}${field('Valor em R$','value','text',d.value,'required inputmode="decimal" placeholder="Ex.: 120,50"')}${field('Data do acontecimento','date','date',d.date,'required')}${select('Paciente (quando pertinente)','patient',patientOptions,d.patient)}${select('Serviço relacionado','service',serviceOptions,d.service)}${select('Profissional relacionado','professional',profOptions,d.professional)}${textArea('Observações para conferência','notes',d.notes)}</div>`:state.step===2?`<div class="fields">${select('Origem do recurso / conta','account',accountOptions,d.account,'Conta pessoal não integra caixa próprio da clínica. Cartão gera obrigação, não débito bancário automático.')}${select('Como ocorreu / ocorrerá','method',[['pix','Pix'],['dinheiro','Dinheiro'],['boleto','Boleto'],['debito','Débito'],['credito','Crédito à vista'],['parcelado','Crédito parcelado'],['cartao-clinica','Compra no cartão da clínica'],['beneficio','VR/VA/Benefício quando aplicável'],['outro','Outro']],d.method)}${select('Cartão cadastrado (se pertinente)','card',[['','Não se aplica'],...state.cards.map(c=>[c.id,c.name])],d.card||'')}${select('Conta destino (somente transferência)','to',accountOptions,d.to||'cx-pj2')}${field('Vencimento ou previsão','due','date',d.due,'required')}${field('Número de parcelas','installments','number',d.installments,'min="1" max="120"')}${field('Data da primeira parcela','first','date',d.first)}${field('Juros total R$ (opcional)','interest','text',d.interest,'inputmode="decimal"')}${field('Origem manual / Outro','other','text',d.other,'placeholder="Descreva quando não houver conta/cartão aplicável"')}${field('Fonte documental/comprovante (opcional)','source','text',d.source||'','placeholder="Identificador ou referência"')}</div>${note('Pix, cartão, benefício, aporte de pessoa física e transferência têm naturezas diferentes. Uma transferência entre contas da clínica não gera receita/despesa; cartão de crédito não debita o caixa até o pagamento da fatura.')}`:`<div class="card">${[['Operação',d.kind],['Descrição',d.desc],['Valor informado',brl(moneyInput(d.value))],['Conta',state.accounts.find(a=>a.id===d.account)?.name||'Origem manual'],['Método',d.method],['Data',dateBR(d.date)],['Vencimento',dateBR(d.due)],['Parcelas',d.installments||'1'],['Juros',brl(moneyInput(d.interest))]].map(([a,b])=>`<div class="row space" style="border-bottom:1px solid var(--border);padding:8px"><span class="muted">${esc(a)}</span><b>${esc(b)}</b></div>`).join('')}</div>${note(state.role==='recepcao'?'A Recepção apenas prepara e envia para validação da Dra. Simone. Nenhum valor movimenta o caixa nesta fase.':'Registro demonstrativo. Previsão não é dinheiro realizado. Parcelas serão obrigações com baixa independente.')}`}
<div class="formfoot">${state.step>1?`<button type="button" class="btn" data-act="finance-prev">← Voltar</button>`:''}<button class="btn primary" type="submit">${state.step<3?'Continuar →':state.role==='recepcao'?'Enviar para validação':'Registrar demonstração'}</button>${btn('Cancelar','finance-reset')}</div></form>`;
return head('FINANCEIRO / ASSISTENTE','Novo lançamento','Operação → origem/forma de pagamento → conferência, sem campos irrelevantes nem duplicidade de caixa.',btn('＋ Criar conta/cartão','modal:account'))+box('Lançamento guiado',main)}
function renderObligations(){const rows=state.obligations.slice().reverse().map(o=>`<tr><td>${esc(o.name)}<div class="tiny">${esc(o.id)}</div></td><td>${dateBR(o.due)}</td><td>${brl(o.value)}</td><td>${badge(o.status)}</td><td>${esc(o.account)}</td><td>${o.status==='previsto'&&permissions()?btn('Pagar parcela','pay-ob:'+o.id,'small'):''}</td></tr>`);return head('FINANCEIRO / COMPROMISSOS','Parcelas e recorrências','Distingue obrigação, competência, vencimento e baixa, com controle de centavos.',btn('＋ Nova obrigação','modal:obligation','primary')+btn('＋ Custo recorrente','modal:recurring'))+`<div class="grid">${stat('Total a pagar',state.obligations.filter(o=>o.status==='previsto').reduce((a,o)=>a+o.value,0),'Obrigações não liquidadas','c4')}${stat('Parcelas pagas',state.obligations.filter(o=>o.status==='liquidado').reduce((a,o)=>a+o.value,0),'Eventos confirmados no simulador','c4')}${stat('Recorrências modelo',state.recurring.reduce((a,o)=>a+o.value,0),'Valores padrão, não caixa','c4')}</div>`+box('Obrigações previstas e pagas',table(['Referência','Vencimento','Valor','Estado','Conta','Ação'],rows))+box('Custos fixos e recorrentes',state.recurring.map(r=>`<div class="task"><div class="detail"><b>${esc(r.name)} · ${brl(r.value)}</b><p>Todo dia ${r.day}; gera ocorrência prevista, nunca pagamento automático.</p></div>${btn('Gerar competência','generate:'+r.id,'small')}</div>`).join('')||'<div class="empty">Use “Custo recorrente” para adicionar uma regra de demonstração.</div>')}
function renderStone(){const rows=state.stone.map(s=>`<tr><td>${esc(s.id)}<div class="tiny">${dateBR(s.date)} · ${esc(s.method)}</div></td><td>${brl(s.gross)}</td><td>${s.fee===null?badge('Taxa ausente'):brl(s.fee)}</td><td>${s.fee===null?'—':brl(s.expected)}</td><td>${s.credit===null?'—':brl(s.credit)}</td><td>${badge(s.status)}</td><td>${s.status!=='conciliado'&&s.fee!==null?btn('Conciliar','reconcile:'+s.id,'small'):''}</td></tr>`);return head('FINANCEIRO / STONE','Cartões e conciliação','Bruto, MDR, antecipação, líquido previsto, crédito e divergência permanecem separados.',btn('＋ Venda cartão demo','modal:stone','primary'))+note('Sem tabela contratual verdadeira: o cálculo automático oficial fica bloqueado. Um usuário autorizado pode informar taxa manual fictícia com fonte. Nenhuma comunicação com a Stone.')+box('Vendas e recebíveis demonstrativos',table(['Operação','Bruto','Taxa MDR','Líquido previsto','Creditado','Estado','Ação'],rows))+box('Regras de cálculo e prevenção',`<div class="task"><div class="detail"><b>Não sobrepor taxa original durante divergência</b><p>Valor esperado e valor depositado podem divergir; a diferença fica aberta para apuração.</p></div>${badge('Proteção')}</div><div class="task"><div class="detail"><b>Tarifas versionadas por clínica e vigência</b><p>O protótipo não carrega tabela Stone oficial. Taxa manual exige fonte e responsável.</p></div>${badge('Pendente contrato')}</div>`)}
function renderRepasses(){const settled=state.tx.filter(t=>t.kind==='entrada'&&t.status==='liquidado'&&t.professional);const rows=state.people.map(p=>{const base=settled.filter(x=>x.professional===p.id).reduce((a,t)=>a+t.net,0);const amount=p.rate===null?null:Math.round(base*p.rate/100);return `<tr><td><b>${esc(p.name)}</b><div class="tiny">${esc(p.notes)}</div></td><td>${brl(base)}</td><td>${p.rate??'—'}${p.rate===null?'':'%'}</td><td>${amount===null?'A definir':brl(amount)}</td><td>${badge('estimativa sem validação')}</td><td>${btn('Editar regra','modal:rate:'+p.id,'small')}</td></tr>`});return head('FINANCEIRO / REPASSES','Repasses profissionais','Percentuais são referências informadas, mas bases de cálculo e contratos ainda dependem de conferência.',btn('Ver histórico','nav:relatorios'))+note('Corte dia 10 e previsão de pagamento dia 15 são parâmetros a confirmar. Nenhum valor desta tela constitui autorização de pagamento.')+box('Apuração ilustrativa por profissional',table(['Profissional','Base recebida','Percentual','Prévia','Estado','Configurar'],rows))+box('Critérios de cálculo',`<div class="task"><div class="detail"><b>Regras com vigência, serviço e contrato</b><p>Evita aplicar novas regras retroativamente; taxas, devoluções, descontos e glosas exigem cláusulas confirmadas.</p></div></div><div class="task"><div class="detail"><b>Patrimônio e equipamentos não são comissão</b><p>Aparelhos, compras, serviços terceirizados e manutenções possuem cadastro de patrimônio/estoque ou despesas, não regra automática de repasse.</p></div></div>`)}
function renderPlans(){const rows=state.plans.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.service)}</td><td>${brl(x.price)}</td><td>${brl(x.patient)}</td><td>${brl(x.price-x.patient)}</td><td>${esc(x.start)}</td></tr>`);return head('FINANCEIRO / CONVÊNIOS','Convênios e parcerias','Clínica predominantemente particular: cadastros e calculadora demonstrativa para condições comerciais específicas.',btn('＋ Contrato fictício','modal:plan','primary'))+note('Particular, plano credenciado e particular com reembolso são situações diferentes. Reembolso particular não cria recebível contra operadora.')+box('Contratos/tabelas de exemplo',table(['Operadora/parceria','Serviço','Valor total','Parte paciente','Parte operadora','Vigência'],rows))+box('Calculadora contratual',`<form id="plan-calc"><div class="fields">${field('Valor contratual R$','total','text','180,00','required')}${field('Coparticipação incluída no total R$','patient','text','30,00','required')}${field('Recebido da operadora R$ (demonstrativo)','received','text','140,00')}${select('Natureza do atendimento','type',[['convenio','Convênio credenciado'],['particular','Particular'],['reembolso','Particular com reembolso']], 'convenio')}</div><div class="formfoot"><button class="btn primary" type="submit">Calcular divisão e diferença</button></div></form><div id="calc-result" class="notice">Use a calculadora para verificar a previsão, valores recebidos e diferenças; sem criar lançamento.</div>`)+box('Tratamento administrativo de pacientes',`<p>Condições comerciais e alertas devem ser objetivos: cortesia autorizada, atendimento prioritário legítimo, solicitação de retorno ou reclamação em andamento. Nunca atribuir automaticamente rótulos depreciativos.</p>`)}
function renderReports(){let tx=state.tx.filter(t=>state.filter==='all'||t.kind===state.filter||t.status===state.filter);const rows=tx.slice().reverse().map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.desc)}</td><td>${esc(t.kind)}</td><td>${brl(t.gross)}</td><td>${brl(t.fees)}</td><td>${brl(t.net)}</td><td>${badge(t.status)}</td></tr>`);return head('FINANCEIRO / HISTÓRICO','Histórico e relatórios','Filtros, rastreabilidade e exportações em Excel verdadeiro e PDF demonstrativo personalizado.',btn('Baixar Excel (.xlsx)','export:xlsx','primary')+btn('Baixar PDF','export:pdf'))+`<div class="row" style="margin-bottom:12px"><label for="report-filter">Exibir: </label><select id="report-filter">${options([['all','Todos'],['entrada','Entradas'],['saida','Saídas'],['previsto','Previstos'],['liquidado','Liquidados'],['aguardando validacao','Aguardando validação']],state.filter)}</select></div>`+box('Operações',table(['Data','Descrição','Tipo','Bruto','Taxa','Líquido','Estado'],rows))+box('Rastreabilidade da demonstração',state.audit.slice(0,12).map(x=>`<div class="task"><div class="detail"><b>${esc(x.message)}</b><p>${esc(x.who)} · ${esc(x.at)} · evento em memória, não auditoria de produção</p></div></div>`).join('')||'<div class="empty">Nenhuma operação realizada nesta sessão.</div>')}
function renderSettings(){return head('FINANCEIRO / CONFIGURAÇÕES','Contas e parâmetros','Cadastros com titular, tipo, origem e vinculação; somente dados demonstrativos.',btn('＋ Conta ou cartão','modal:account','primary'))+`<div class="grid"><div class="c6">${box('Contas e carteiras',state.accounts.map(a=>`<div class="task"><div class="detail"><b>${esc(a.name)}</b><p>${esc(a.owner)} · ${esc(a.kind)} · saldo demonstrativo inicial ${brl(a.opening)}</p></div></div>`).join(''))}</div><div class="c6">${box('Cartões e benefícios',state.cards.map(a=>`<div class="task"><div class="detail"><b>${esc(a.name)}</b><p>${esc(a.kind)} · ${esc(a.owner)}</p></div></div>`).join(''))}</div></div>`+box('Princípios de configuração',`<p>Conta pessoal não entra no caixa próprio; benefício não é dinheiro livre; compras no crédito geram obrigação de fatura. Serviços, categorias, regras e contas são versionados na implementação real. Não existem chaves Supabase, cobrança, Stone ou salários conectados neste pacote.</p>`)}
function patientView(){switch(state.page){case 'fila':return viewIntakes();case 'prontuario':return viewRecords();default:return viewPatientDirectory()}}
function viewPatientDirectory(){return head('M2 / ATENDIMENTO E PACIENTES','Cadastro único de pacientes','Identidade, contatos, responsável legal e cobrança. CPF é atributo condicional, não ID técnico.',btn('＋ Paciente fictício','modal:patient','primary'))+note('Todos os pacientes são exemplos inventados. O sistema não recebe prontuários reais. Dados clínicos são separados dos administrativos.')+box('Pacientes da demonstração',state.patients.map(p=>`<div class="task"><div class="detail"><b>${esc(p.id)} · ${esc(p.name)}</b><p>${esc(p.phone)} · ${esc(p.email)}</p><p>${p.tag?`Condição administrativa: ${esc(p.tag)} · ${esc(p.note)}`:'Sem alerta administrativo'} ${p.legal?' · Responsável: '+esc(p.legal):''}</p></div><div class="cell-actions">${btn('Ver história','record:'+p.id,'small')}${btn('Abrir atendimento','new-intake:'+p.id,'small')}</div></div>`).join(''))+box('Segurança e deduplicação',`<p>Busca por nome/CPF quando legítimo e disponível, com revisão de possíveis duplicidades. Não unir cadastros automaticamente nem inferir dados de saúde. A recepção usa cadastro administrativo mínimo e não visualiza evolução clínica.</p>`)}
function viewIntakes(){return head('M2 / FLUXO ASSISTENCIAL','Fila central e atendimento','Agendamento, chegada, fila, ato clínico e cobrança são acontecimentos separados.',btn('＋ Atendimento avulso / encaixe','modal:intake','primary'))+box('Fila operacional',state.intakes.map(i=>`<div class="task"><div class="detail"><b>${esc(person(i.patient))} · ${esc(i.type)}</b><p>${esc(i.id)} · ${dateBR(i.date)} · Profissional: ${esc(prof(i.professional))} · ${esc(i.notes||'')}</p></div><div class="cell-actions">${badge(i.status)}${btn('Próxima etapa','intake-next:'+i.id,'small')}</div></div>`).join('')||'<div class="empty">Nenhuma pessoa aguardando nesta sessão. Um check-in pode criar evento de fila sintético.</div>')+note('A recepção ou a profissional podem organizar a fila. Atos clínicos e assinaturas exigem profissional habilitado; esta simulação não produz prontuário clínico válido.')}
function viewRecords(){return head('M2 / PRONTUÁRIO','Prontuário longitudinal','Linha do tempo clínica demonstrativa; documento externo preservado e resumo validado são registros distintos.')+box('Pacientes e linha do tempo de exemplos',state.patients.map(p=>`<div class="task"><div class="detail"><b>${esc(p.name)}</b><p>ID interno: ${esc(p.id)} · prontuário longitudinal fictício vinculado, sem novos prontuários por retorno.</p><p>Exames → avaliação → evolução → documentos externos e termos AASI, conforme permissão clínica.</p></div>${btn('Ver eventos','record:'+p.id,'small')}</div>`).join(''))+note('Esta tela é demonstrativa. Não implementa prontuário eletrônico, assinaturas da Fonoaudiologia, guarda legal nem controle assistencial em banco.')}
function agendaView(){if(state.page==='comunicacoes')return head('M3 / AGENDA','Comunicação assistida','E-mail simulado, WhatsApp manual e registros retrospectivos. Nada é enviado.',btn('＋ Registrar contato','modal:message','primary'))+box('Interações e mensagens',state.messages.map(m=>`<div class="task"><div class="detail"><b>${esc(m.method)} · ${esc(person(m.patient))}</b><p>${esc(m.text)} · ${esc(m.date)} · Registro manual, não comprova mensagem enviada pelo SGI.</p></div></div>`).join('')||'<div class="empty">Registre um contato fictício para observar o histórico de comunicações.</div>')+note('Confirmação de presença não cancela agendamento por falta de resposta. Remarcação/cancelamento exige aprovação inicial de pessoa autorizada.');return head('M3 / AGENDA','Agenda e encaixes','Calendário operacional e solução de imprevistos; sem envios reais ou reservas em banco.',btn('＋ Agendamento','modal:appointment','primary')+btn('Registrar WhatsApp','nav:comunicacoes'))+box('Agenda e compromissos demonstrativos',state.appointments.map(a=>`<div class="task"><div class="detail"><b>${dateBR(a.date)} às ${esc(a.time)} · ${esc(person(a.patient))}</b><p>${esc(prof(a.professional))} · ${esc(a.source)} · ${esc(a.notes)}</p></div><div class="cell-actions">${badge(a.status)}${btn('Chegada','checkin:'+a.id,'small')}${btn('Solicitar encaixe','request-encaixe:'+a.id,'small')}</div></div>`).join(''))+note('Encaixe deve ser autorizado inicialmente pela profissional. Atraso/falta não dispara cancelamento ou cobrança por relógio.')}
function documentsView(){if(state.page==='termos')return head('M4 / DOCUMENTOS','Termos AASI','Teste, entrega, devolução, troca e garantia, sempre vinculados à identidade da unidade e ao paciente.',btn('＋ Termo sintético','modal:document','primary'))+box('Emissões de exemplo',docList())+note('Gerar um termo não movimenta estoque nem liquida venda. Nenhum documento desta demonstração possui assinatura válida.');return head('M4 / DOCUMENTOS','Biblioteca e modelos','Arquivos privados e controle de versões na arquitetura futura; a prévia pública usa somente dados sintéticos.',btn('＋ Criar termo fictício','modal:document','primary'))+box('Modelos preparados',`<div class="grid">${['Termo de teste/empréstimo AASI','Termo de entrega','Termo de devolução','Orientações de adaptação','Termo de garantia','Modelo institucional'].map(t=>`<div class="card c6"><h3>${t}</h3><p>Preenchimento guiado · revisão · versão</p>${btn('Prévia exemplo','preview-template:'+t,'small')}</div>`).join('')}</div>`)+box('Arquivos sintéticos',docList())}
function docList(){return state.documents.map(d=>`<div class="task"><div class="detail"><b>${esc(d.type)}</b><p>${esc(d.version)} · ${esc(d.serial)} · ${esc(person(d.patient))}</p></div><div class="cell-actions">${badge(d.status)}${btn('Prévia','preview-doc:'+d.id,'small')}</div></div>`).join('')}
function stockView(){if(state.page==='movimentos')return head('M5 / ESTOQUE','Movimentações do AASI','Consignação, teste, venda, devolução e assistência têm autorização e histórico próprios.',btn('＋ Movimentação simulada','modal:stock','primary'))+box('Unidades e custódia',inventoryList())+note('Confirmação da movimentação é independente da emissão de termo e da cobrança financeira. Não há movimento físico real.');if(state.page==='insumos')return head('M5 / ESTOQUE','Insumos e inventário','Quantidades, lotes e validade conforme natureza do insumo. Nenhum número de série obrigatório para materiais comuns.',btn('＋ Inventário fictício','modal:inventory','primary'))+box('Controle por categoria',`<div class="task"><div class="detail"><b>Pilhas auditivas · Exemplo</b><p>20 unidades fictícias · mínimo 8 · lote hipotético, validade quando aplicável</p></div>${badge('ilustrativo')}</div><div class="task"><div class="detail"><b>Materiais de adaptação · Exemplo</b><p>Quantidade sob conferência, sem vinculação financeira direta.</p></div>${badge('ilustrativo')}</div>`);return head('M5 / ESTOQUE','Estoque e rastreabilidade','Cada AASI tem série, lateralidade, propriedade, custodiante e disponibilidade próprios.',btn('＋ Movimentação','modal:stock','primary'))+`<div class="grid">${[['Disponíveis',state.inventory.filter(i=>i.status==='disponivel').length],['Em teste',state.inventory.filter(i=>i.status==='teste').length],['Em conferência',state.inventory.filter(i=>i.status==='conferencia').length],['Consignados',state.inventory.filter(i=>i.ownership.includes('consignante')).length]].map(([t,n])=>`<div class="card c3 stat"><div class="label">${t}</div><div class="value">${n}</div><small>Contagem fictícia por condição</small></div>`).join('')}</div>`+box('Aparelhos individuais',inventoryList())+note('Consignado identifica PROPRIEDADE; não é um estado exclusivo de “disponível” ou “em teste”. Não some esses indicadores como se não houvesse sobreposição.')}
function inventoryList(){return state.inventory.map(i=>`<div class="task"><div class="detail"><b>${esc(i.serial)} · ${esc(i.model)}</b><p>${esc(i.ownership)} · Custódia: ${esc(i.custody)} · ${i.patient?'Vinculado: '+esc(person(i.patient)):''}</p><p>${esc(i.history.slice(-2).join(' → '))}</p></div><div class="cell-actions">${badge(i.status)}${btn('Histórico','stock-detail:'+i.id,'small')}</div></div>`).join('')}
function govView(){if(state.page==='permissoes')return head('M6 / GOVERNANÇA','Permissões e solicitações','Contas, convites e delegações são governados pelo backend e Central AA.dev; aqui só há simulação.',btn('＋ Solicitação fictícia','modal:gov','primary'))+box('Ciclo de solicitação',`<div class="task"><div class="detail"><b>Solicitar usuário → Central AA.dev → convite → confirmação → termos jurídicos → licença → ativo</b><p>Simulação sem conta real; ativação técnica nunca ocorre por esta página.</p></div></div>`+state.tasks.map(t=>`<div class="task"><div class="detail"><b>${esc(t.name)}</b><p>${esc(t.notes)}</p></div>${badge('pendente — fictício')}</div>`).join(''))+note('Desenvolvedor e auditoria técnica pertencem à Central AA.dev; não existe entrada técnica de produção neste PWA público.');if(state.page==='catalogo')return head('M6 / CATÁLOGO','Catálogo Mestre','Definições únicas com regras financeiras, agendas e documentos específicos por módulo.',btn('＋ Serviço fictício','modal:service','primary'))+box('Serviços por clínica',state.services.map(s=>`<div class="task"><div class="detail"><b>${esc(s.id)} · ${esc(s.name)}</b><p>Tempo de referência: ${s.duration} min · Preço particular ilustrativo: ${s.price===null?'A definir':brl(s.price)}</p></div></div>`).join(''))+note('Editar valor ou denominação hoje não deve reescrever vendas ou documentos antigos.');return head('M6 / CADASTRO','Identidades e vínculos','Pessoa ≠ paciente ≠ colaborador ≠ conta de login ≠ permissão.',btn('Criar solicitação de acesso','modal:gov','primary'))+box('Equipe fictícia',state.people.map(p=>`<div class="task"><div class="detail"><b>${esc(p.name)}</b><p>Vínculo assistencial definido conforme trabalho e contrato; não concede acesso financeiro por título.</p></div>${badge('Exemplo')}</div>`).join(''))+note('Separação por clínica/tenant, RLS, MFA, recuperação, convites e concessões reais dependem de backend e não estão ativos nesta demonstração.')}
function hrView(){if(state.page==='protocolos')return head('M7 / RH','Protocolos e terceirizados','Triagem por categoria e permissão, acesso externo delegado e encaminhamento manual alternativo.',btn('＋ Protocolo fictício','modal:hr','primary'))+box('Solicitações demonstrativas',state.hr.map(h=>`<div class="task"><div class="detail"><b>${esc(h.category)} · ${esc(h.person)}</b><p>${esc(h.notes)} · Responsável: ${esc(h.reviewer)}</p></div>${badge(h.status)}</div>`).join(''))+note('Nenhuma folha, eSocial, REP, obrigação legal ou afastamento médico é realizado por esta interface.');return head('M7 / RH','Minha área do colaborador','Documentos, comunicação de ausências e solicitações; atendimento exclusivo aos vínculos pertinentes.',btn('＋ Solicitação','modal:hr','primary'))+box('Minha Área — exemplo',`<div class="grid">${['Meus documentos','Férias','Ausências','Falar com RH'].map(t=>`<div class="card c6"><h3>${t}</h3><p>Dados sintéticos; acesso restrito no sistema real.</p>${btn('Abrir exemplo','nav:protocolos','small')}</div>`).join('')}</div>`)+note('Atestados médicos têm sigilo especial; chefias operacionais veem somente disponibilidade e condições necessárias à escala.')}
function modalHTML(kind,arg=''){const form=(id,body,submit='Salvar exemplo')=>`<form id="${id}"><div class="fields">${body}</div><div class="formfoot"><button type="submit" class="btn primary">${submit}</button>${btn('Cancelar','modal-close')}</div></form>`;switch(kind){
case'notice':return ['Comunicado para equipes',form('notice-form',field('Assunto','title','text','','required')+textArea('Texto do comunicado','body','')+select('Público autorizado','scope',[['Todos','Equipe da clínica'],['Recepção','Recepção'],['Financeiro','Financeiro'],['Profissionais','Profissionais']]),'Publicar somente nesta sessão')];
case'account':return ['Nova conta ou cartão fictício',form('account-form',field('Descrição de identificação','name','text','','required')+select('Tipo de origem','kind',[['pj','Conta PJ'],['cash','Caixa físico'],['personal','Conta PF/terceiro'],['credit','Cartão de crédito'],['benefit','Cartão VA/VR/benefício']])+field('Titular/proprietário','owner','text','Clínica Áudio S.A.','required')+field('Saldo inicial demonstrativo R$ (contas)','opening','text','0,00'),'Adicionar cadastro fictício')];
case'obligation':return ['Nova obrigação parcelada',form('ob-form',field('Descrição','name','text','','required')+field('Total contratado R$','total','text','','required inputmode="decimal"')+field('Juros totais R$','interest','text','0,00')+field('Quantidade de parcelas','count','number','3','required min="1" max="120"')+field('Primeiro vencimento','first','date',DEMO_DATE,'required')+select('Conta para baixa futura','account',appOptions,'cx-pj'),'Gerar parcelas previstas')];
case'recurring':return ['Nova recorrência demonstrativa',form('recurring-form',field('Nome do compromisso','name','text','','required')+field('Valor mensal previsto R$','value','text','','required')+field('Dia do vencimento (1 a 31)','day','number','30','min="1" max="31" required')+select('Conta','account',appOptions,'cx-pj'),'Criar regra de previsão')];
case'stone':return ['Venda por cartão fictícia',form('stone-form',field('Descrição da venda','name','text','Venda demonstrativa','required')+field('Valor bruto R$','gross','text','100,00','required')+select('Modalidade','method',[['credito','Crédito'],['debito','Débito'],['parcelado','Crédito parcelado']])+field('Quantidade de parcelas','installments','number','1','min="1" max="36"')+field('Taxa MDR manual % (em branco = não configurada)','rate','text','')+field('Antecipação R$ (manual, quando houver)','advance','text','0,00')+field('Fonte e justificativa do cálculo manual','source','text','','placeholder="Obrigatória para usar taxa manual"'),'Preparar recebível fictício')];
case'plan':return ['Novo contrato fictício de convênio',form('plan-form',field('Operadora ou parceria','name','text','','required')+select('Serviço','service',serviceOptions,'SV-01')+field('Valor total contratado R$','price','text','','required')+field('Coparticipação paciente incluída R$','patient','text','0,00')+field('Vigência inicial','start','date',DEMO_DATE,'required'),'Cadastrar contrato simulado')];
case'patient':return ['Paciente fictício',form('patient-form',field('Nome fictício','name','text','','required')+field('Contato fictício','phone','text','(11) 90000-0000')+field('E-mail demonstrativo (.invalid)','email','email','teste@exemplo.invalid')+field('Representante legal (se aplicável)','legal','text','')+select('Contexto administrativo objetivo','tag',[['','Nenhum'],['cortesia','Cortesia autorizada'],['prioridade','Preferência operacional autorizada'],['pendencia','Pendência administrativa']])+textArea('Observação objetiva','note'),'Criar identidade fictícia')];
case'intake':return ['Novo atendimento demonstrativo',form('intake-form',select('Paciente','patient',patientOptions,'PAC-001')+select('Profissional','professional',profOptions,'marcia')+select('Origem do atendimento','type',[['avulso','Avulso autorizado'],['encaixe','Encaixe solicitado'],['agendado','Agendado']])+textArea('Motivo administrativo breve','notes',''),'Iniciar fluxo sintético')];
case'appointment':return ['Agendamento fictício',form('appointment-form',select('Paciente','patient',patientOptions,'PAC-001')+select('Profissional','professional',profOptions,'marcia')+field('Data','date','date',DEMO_DATE,'required')+field('Hora','time','time','09:00','required')+textArea('Descrição administrativa','notes',''),'Registrar agendamento simulado')];
case'message':return ['Contato realizado fora do SGI',form('message-form',select('Paciente','patient',patientOptions,'PAC-001')+select('Origem do contato','method',[['WhatsApp manual','WhatsApp manual'],['Telefone','Telefone'],['Presencial','Presencial'],['E-mail externo','E-mail externo']])+field('Data informada','date','date',DEMO_DATE)+textArea('Resumo objetivo da conversa','text',''),'Registrar histórico retrospectivo')];
case'document':return ['Novo termo AASI — prévia',form('document-form',select('Paciente','patient',patientOptions,'PAC-001')+select('Finalidade','type',[['Termo de teste AASI','Teste/empréstimo'],['Termo de entrega','Entrega'],['Termo de devolução','Devolução'],['Termo de troca','Troca'],['Termo de garantia','Garantia']])+select('Número de série','serial',state.inventory.map(i=>[i.serial,i.serial+' · '+i.model]))+textArea('Condições e observações','notes',''),'Criar rascunho não assinado')];
case'stock':return ['Movimentação física fictícia',form('stock-form',select('Unidade individual','id',state.inventory.map(i=>[i.id,i.serial+' · '+i.status]))+select('Nova situação','status',[['reservado','Reservado'],['teste','Em teste'],['conferencia','Devolvido — conferir'],['disponivel','Disponível após conferência'],['assistencia','Em assistência'],['vendido','Vendido / entregue']])+select('Paciente (quando pertinente)','patient',patientOptions)+field('Custódia/localização','custody','text','Clínica')+textArea('Motivo/evidência de conferência','notes',''),'Confirmar movimento em memória')];
case'inventory':return ['Inventário de insumos — simulação',form('inventory-form',field('Categoria','name','text','Pilhas auditivas')+field('Quantidade contada','count','number','20')+textArea('Evidência/observação','notes',''),'Registrar conferência fictícia')];
case'gov':return ['Solicitação de acesso / alteração',form('gov-form',field('Solicitante (fictício)','name','text','Gestão da clínica','required')+select('Tipo','type',[['novo_usuario','Novo usuário'],['permissao','Delegação ou permissão'],['dados','Dados institucionais']])+textArea('Justificativa','notes',''),'Enviar solicitação de demonstração')];
case'service':return ['Novo serviço do catálogo',form('service-form',field('Nome do serviço','name','text','','required')+field('Duração de referência (minutos)','duration','number','60','min="10"')+field('Preço de referência R$','price','text',''),'Criar item fictício')];
case'hr':return ['Protocolo de RH fictício',form('hr-form',field('Colaborador fictício','person','text','Colaborador Exemplo','required')+select('Tipo de solicitação','category',[['Férias','Férias'],['Documento','Documento'],['Ausência','Comunicação de ausência'],['Consulta','Falar com RH']])+textArea('Informações administrativas (não insira saúde real)','notes',''),'Criar protocolo demonstrativo')];
case'ocr':return ['Leitura de comprovante — demonstração',`<p>Esta edição não contém serviço de OCR. Você pode selecionar um arquivo local apenas para visualizar seu nome, sem enviá-lo para a internet. A extração automática e a conferência dos campos exigem desenvolvimento e homologação posteriores.</p>${form('ocr-form',`<div class="field full"><label for="ocr-file">Arquivo demonstrativo</label><input type="file" name="attachment" id="ocr-file" accept="image/*,.pdf"><small class="help">Nada é transmitido ou gravado fora da memória.</small></div>`,'Verificar arquivo local')}`];
case'rate':{const p=state.people.find(p=>p.id===arg);return ['Prévia de regra de repasse',form('rate-form',`<input type="hidden" name="id" value="${esc(arg)}">${field('Profissional','name','text',p?.name||'', 'disabled')}${field('Percentual ilustrativo','rate','number',p?.rate??'','min="0" max="100" step="0.01"')}${field('Base contratual validada?','base','text','Pendente','readonly')}${textArea('Condições por serviço e vigência','notes',p?.notes||'')}`,'Salvar somente no exemplo')]}
case'credit':return ['Conciliar crédito bancário fictício',form('credit-form',`<input type="hidden" name="id" value="${esc(arg)}">${field('Valor creditado no extrato demonstrativo R$','credit','text','0,00','required')}${select('Conta creditada','account',appOptions,'cx-pj')}${field('Data do crédito','date','date',DEMO_DATE,'required')}${textArea('Evidência ou diferença','notes','')}`,'Confirmar crédito simulado')];
default:return ['Aviso','<p>Esta ação será detalhada na próxima etapa.</p>'+btn('Fechar','modal-close')];}}
function openModal(kind,arg=''){const [title,body]=modalHTML(kind,arg);let el=document.createElement('div');el.id='active-modal';el.className='modal-overlay';el.setAttribute('role','presentation');el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modaltitle"><div class="row space"><h2 id="modaltitle">${esc(title)}</h2><button class="btn small" type="button" data-act="modal-close" aria-label="Fechar diálogo">✕</button></div>${body}</div>`;document.body.appendChild(el);el.querySelector('input:not([type=hidden]),select,button')?.focus()}
function closeModal(){document.querySelector('#active-modal')?.remove()}
function getForm(form){const o=Object.fromEntries(new FormData(form).entries());for(const k of Object.keys(o))if(typeof o[k]==='string')o[k]=o[k].trim();return o}
function nextMonths(date,i,day){let [y,m]=date.split('-').map(Number);let dt=new Date(y,m-1+i,1);let final=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate();return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(Math.min(Number(day)||dt.getDate(),final)).padStart(2,'0')}`}
function makeObligations(name,total,interest,count,first,account){if(count<1||count>120||!Number.isInteger(count))throw Error('Parcelas devem ser entre 1 e 120');if(total<=0)throw Error('Valor contratado inválido');const all=total+interest;const per=Math.floor(all/count);const day=Number(first.slice(-2));let batch=uid('PAR');for(let i=0;i<count;i++)state.obligations.push({id:batch+'-'+(i+1),name:`${name} (${i+1}/${count})`,value:per+(i===count-1?all-per*count:0),due:nextMonths(first,i,day),account,status:'previsto',paid:''});return batch}
function handleSubmit(ev){const f=ev.target;if(!f.id)return;ev.preventDefault();const d=getForm(f);try{switch(f.id){
case'finance-entry':{if(state.step===1){state.draft={...(state.draft||{}),...d,kind:d.operation};if(!d.desc||moneyInput(d.value)<=0)throw Error('Informe descrição e valor positivo.');state.step=2;render();return;}if(state.step===2){state.draft={...state.draft,...d};if(d.account==='manual'&&!d.other)throw Error('Informe a origem manual.');if(d.kind==='transferencia'&&d.account===d.to)throw Error('Origem e destino precisam ser diferentes.');state.step=3;render();return;}const t=state.draft;const value=moneyInput(t.value),interest=moneyInput(t.interest);if(value<=0)throw Error('Valor inválido.');if(t.kind==='transferencia'){if(state.role==='recepcao')throw Error('Transferências da recepção exigem solicitação específica, sem execução nesta demo.');if(!t.account||!t.to||t.account===t.to||t.account==='manual'||t.to==='manual')throw Error('Selecione origem e destino cadastrados distintos.');if(state.accounts.find(a=>a.id===t.account)?.kind==='personal'||state.accounts.find(a=>a.id===t.to)?.kind==='personal')throw Error('Conta PF exige operação de aporte/reembolso documentada, não transferência interna da clínica.');state.transfers.push({id:uid('TRF'),from:t.account,to:t.to,value,date:t.date});audit('Transferência interna fictícia registrada sem receita/saída');}else if(t.method==='cartao-clinica'||t.method==='beneficio'){if(t.kind==='entrada')throw Error('Entrada não pode ser registrada como compra no cartão da clínica.');if(!t.card)throw Error('Selecione cartão aplicável.');const c=state.cards.find(x=>x.id===t.card);if(!c)throw Error('Cartão não encontrado.');if(t.method==='beneficio'&&c.kind!=='benefit')throw Error('Selecione cartão de benefício.');if(t.method==='cartao-clinica'&&c.kind!=='credit')throw Error('Selecione cartão de crédito.');makeObligations(`${t.desc} · ${c.name}`,value,interest,Number(t.installments)||1,t.first||t.due,t.account);audit('Obrigação do cartão criada, sem débito do saldo bancário');}else if(Number(t.installments)>1&&t.kind==='saida'){makeObligations(t.desc,value,interest,Number(t.installments),t.first||t.due,t.account);audit('Compra parcelada cria obrigações, não baixa total do caixa');}else{let status=state.role==='recepcao'?'aguardando validacao':'previsto';const txn={id:uid('FIN'),kind:t.kind,desc:t.desc,patient:t.patient||'',service:t.service||'',professional:t.professional||'',gross:value,fees:0,net:value,account:t.account,date:t.date,due:t.due,paid:'',method:t.method,status,owner:state.role,source:t.source||t.other||'Formulário de demonstração',notes:t.notes||''};state.tx.push(txn);audit('Lançamento '+txn.id+' em estado '+status);}state.draft=null;state.step=1;toast('Operação demonstrativa registrada. Não houve transação real.');go('finance','lancamentos');break;}
case'account-form':{if(!d.name||!d.owner)throw Error('Identifique descrição e titular.');if(['credit','benefit'].includes(d.kind))state.cards.push({id:uid('CRD'),name:d.name,kind:d.kind,owner:d.owner,limit:null});else state.accounts.push({id:uid('ACC'),name:d.name,kind:d.kind,owner:d.owner,opening:moneyInput(d.opening)});audit('Cadastro de origem financeira fictícia');break;}
case'ob-form':{makeObligations(d.name,moneyInput(d.total),moneyInput(d.interest),Number(d.count),d.first,d.account);audit('Parcelas geradas com valores exatos em centavos');break;}
case'recurring-form':{let day=Number(d.day);if(day<1||day>31||moneyInput(d.value)<=0)throw Error('Confira valor e dia do mês');state.recurring.push({id:uid('REC'),name:d.name,value:moneyInput(d.value),day,account:d.account});audit('Regra recorrente fictícia registrada');break;}
case'stone-form':{const gross=moneyInput(d.gross),r=d.rate===''?null:pct(d.rate),advance=moneyInput(d.advance);if(gross<=0||r!==null&&(r<0||r>100))throw Error('Valor ou percentual inválido');if(r!==null&&!d.source)throw Error('Taxa manual exige fonte/justificativa.');const fee=r===null?null:Math.round(gross*r/100),expected=fee===null?null:gross-fee-advance;if(expected!==null&&expected<0)throw Error('Taxas e antecipação ultrapassam o bruto.');state.stone.unshift({id:uid('STN'),date:DEMO_DATE,name:d.name,method:d.method,installments:Number(d.installments)||1,gross,fee,advance,expected,credit:null,status:fee===null?'taxa pendente':'recebível previsto',source:d.source||''});audit('Venda Stone simulada; sem crédito bancário');break;}
case'plan-form':{let price=moneyInput(d.price),patient=moneyInput(d.patient);if(price<=0||patient<0||patient>price)throw Error('Coparticipação precisa estar incluída no total.');state.plans.push({name:d.name,service:state.services.find(x=>x.id===d.service)?.name||'Outro',price,patient,start:d.start});audit('Parceria contratual fictícia');break;}
case'plan-calc':{let total=moneyInput(d.total),part=moneyInput(d.patient),received=moneyInput(d.received);if(total<=0||part>total||part<0)throw Error('Coparticipação inválida.');let expected=d.type==='convenio'?total-part:0,rec=d.type==='convenio'?received:0;let el=$('#calc-result');el.innerHTML=`<div><b>Total contratado:</b> ${brl(total)} · <b>Paciente:</b> ${brl(d.type==='convenio'?part:total)}</div><div><b>Operadora prevista:</b> ${brl(expected)} · <b>Recebido da operadora:</b> ${brl(rec)}</div><div><b>Diferença a conciliar:</b> ${brl(expected-rec)} — sem presumir glosa definitiva.</div>`;return;}
case'patient-form':{if(!d.name.toLowerCase().includes('exemplo')&&!d.name.toLowerCase().includes('fictício'))throw Error('Use apenas nomes claramente fictícios, com “Exemplo” ou “Fictício”.');state.patients.push({id:uid('PAC'),name:d.name,phone:d.phone,email:d.email,legal:d.legal,tag:d.tag,note:d.note});audit('Paciente sintético adicionado');break;}
case'intake-form':{if(!d.patient||!d.professional)throw Error('Selecione paciente e profissional');state.intakes.push({id:uid('ATD'),patient:d.patient,professional:d.professional,type:d.type,date:DEMO_DATE,notes:d.notes,status:'em espera'});audit('Atendimento fictício criado');break;}
case'appointment-form':{if(!d.patient||!d.professional||!d.date)throw Error('Preencha campos necessários.');state.appointments.push({id:uid('AG'),patient:d.patient,professional:d.professional,date:d.date,time:d.time,status:'agendado',source:'agendamento',notes:d.notes});audit('Agendamento sintético criado');break;}
case'message-form':{if(!d.patient)throw Error('Selecione um paciente fictício');state.messages.unshift({id:uid('MSG'),...d});audit('Interação retrospectiva manual fictícia');break;}
case'document-form':{if(!d.patient||!d.serial)throw Error('Selecione paciente e número de série');state.documents.unshift({id:uid('DOC'),type:d.type,patient:d.patient,serial:d.serial,status:'rascunho não assinado',version:'V1 · exemplo',notes:d.notes});audit('Termo fictício gerado sem assinatura');break;}
case'stock-form':{let i=state.inventory.find(x=>x.id===d.id);if(!i)throw Error('Unidade não encontrada');if(d.status==='disponivel'&&i.status==='conferencia'&&!d.notes)throw Error('Retorno ao disponível exige evidência de conferência.');if(d.status==='vendido'&&!d.notes)throw Error('Venda exige referência documental e confirmação comercial própria.');if(d.status==='teste'&&!d.patient)throw Error('Teste exige paciente sintético vinculado.');i.status=d.status;i.patient=d.patient||'';i.custody=d.custody;i.history.push(`${DEMO_DATE}: ${d.status} — ${d.notes||'movimento demonstrativo'}`);audit('Movimento de AASI fictício '+i.serial);break;}
case'inventory-form':{audit('Conferência de insumos fictícia '+d.name+' = '+d.count);break;}
case'gov-form':{state.tasks.unshift({id:uid('GOV'),name:`${d.type} · ${d.name}`,notes:d.notes});audit('Solicitação governança em memória');break;}
case'service-form':{state.services.push({id:uid('SV'),name:d.name,duration:Number(d.duration)||60,price:d.price?moneyInput(d.price):null});audit('Serviço fictício adicionado ao catálogo');break;}
case'hr-form':{state.hr.unshift({id:uid('RH'),person:d.person,category:d.category,notes:d.notes,status:'em triagem',reviewer:'Responsável por categoria'});audit('Protocolo RH demonstrativo');break;}
case'notice-form':{if(!permissions())throw Error('Somente gestão simulada publica avisos da clínica.');state.notices.unshift({id:uid('AV'),title:d.title,body:d.body,scope:d.scope,date:DEMO_DATE});audit('Aviso fictício criado para a equipe');break;}
case'rate-form':{let p=state.people.find(p=>p.id===d.id),rate=d.rate===''?null:pct(d.rate);if(!p||rate!==null&&(rate<0||rate>100))throw Error('Percentual inválido');p.rate=rate;p.notes=d.notes;p.base='pendente';audit('Regra de repasse alterada em simulação sem validação contratual');break;}
case'credit-form':{const st=state.stone.find(x=>x.id===d.id),credit=moneyInput(d.credit);if(!st||st.fee===null)throw Error('Taxa ainda não configurada');if(credit<0)throw Error('Valor negativo');if(st.credit!==null)throw Error('Crédito desta venda já confirmado; não duplicar');st.credit=credit;st.status=credit===st.expected?'conciliado':'divergencia';st.account=d.account;st.notes=d.notes;st.creditDate=d.date;state.tx.push({id:uid('FIN'),kind:'entrada',desc:'Depósito Stone '+st.id,patient:'',service:'',professional:'',gross:st.gross,fees:st.fee+st.advance,net:credit,account:d.account,method:'stone',status:'liquidado',date:d.date,due:d.date,paid:d.date,owner:state.role,source:st.id});audit('Crédito Stone registrado uma única vez, preservando tarifa original');break;}
case'ocr-form':{const file=f.querySelector('input[type=file]').files[0];toast(file?`Arquivo local reconhecido: ${file.name}. Nenhum OCR executado.`:'Nenhum arquivo selecionado');closeModal();return;}
default:return;
}closeModal();toast('Exemplo atualizado nesta sessão, sem envio a servidor.');render();}catch(err){toast('Verifique: '+err.message);console.warn('Validação demonstrativa:',err.message)}}
function showMessage(title,body){const elem=document.createElement('div');elem.id='active-modal';elem.className='modal-overlay';elem.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="row space"><h2>${esc(title)}</h2>${btn('✕','modal-close','small')}</div><div>${body}</div><div class="formfoot">${btn('Fechar','modal-close','primary')}</div></div>`;document.body.appendChild(elem)}
function act(a){if(!a)return;const [name,...rest]=a.split(':'),arg=rest.join(':');if(name==='home'){go('home');return}if(name==='open'){go(arg);return}if(name==='nav'){go(state.app,arg);return}if(name==='theme'){state.theme=state.theme==='light'?'dark':'light';render();return}if(name==='modal'){openModal(arg.split(':')[0],arg.split(':').slice(1).join(':'));return}if(name==='modal-close'){closeModal();return}if(name==='finance-reset'){state.draft=null;state.step=1;go('finance','lancamentos');return}if(name==='finance-prev'){state.step=Math.max(1,state.step-1);render();return}
if(name==='notices'){showMessage('Avisos e tarefas demonstrativas',state.notices.map(n=>`<div class="task"><div class="detail"><b>${esc(n.title)}</b><p>${esc(n.body)} · Escopo ${esc(n.scope)}</p></div></div>`).join('')+(permissions()?btn('＋ Publicar aviso','modal:notice'):'')+`<p class="tiny">Nenhuma mensagem é enviada para pessoas reais.</p>`);return}
if(name==='mobile-menu'){showMessage('Navegação do aplicativo',(menus[state.app]||[]).map(([id,l])=>`<button class="navbtn" style="color:var(--ink);background:var(--surface2);margin:4px 0" data-act="nav:${id}">${esc(l)}</button>`).join(''));return}
if(name==='approve'){if(!permissions())return toast('Somente a Dra. Simone aprova solicitações da recepção nesta demonstração.');let t=state.tx.find(x=>x.id===arg);if(t&&t.status==='aguardando validacao'){t.status='previsto';audit('Rascunho '+arg+' aprovado pela Dra. Simone; ainda não liquidado');render();toast('Aprovado como lançamento previsto, sem liquidação.')}return}
if(name==='settle'){if(!permissions())return toast('Confirmação financeira exige permissão simulada da direção.');let t=state.tx.find(x=>x.id===arg);if(t&&t.status==='previsto'){t.status='liquidado';t.paid=DEMO_DATE;audit('Liquidação fictícia do lançamento '+arg);render();toast('Liquidação simulada registrada.')}return}
if(name==='detail'){const t=state.tx.find(x=>x.id===arg);if(t){const detailRows=[['Tipo',t.kind],['Estado',t.status],['Bruto',brl(t.gross)],['Taxas',brl(t.fees)],['Líquido',brl(t.net)],['Data',dateBR(t.date)],['Vencimento',dateBR(t.due)],['Baixa',dateBR(t.paid)],['Fonte',t.source]].map(([k,v])=>`<div class="row space" style="padding:6px;border-bottom:1px solid var(--border)"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');showMessage('Detalhes do lançamento '+t.id,`<p><b>${esc(t.desc)}</b></p>`+detailRows+note('Aprovação e liquidação permanecem separadas. Dados e histórico são fictícios.'));}return}
if(name==='pay-ob'){if(!permissions())return toast('Operação exige autorização da direção simulada.');const o=state.obligations.find(x=>x.id===arg);if(o&&o.status==='previsto'){o.status='liquidado';o.paid=DEMO_DATE;state.tx.push({id:uid('FIN'),kind:'saida',desc:'Pagamento parcela '+o.name,patient:'',service:'',professional:'',gross:o.value,fees:0,net:o.value,account:o.account,method:'pix',status:'liquidado',date:DEMO_DATE,due:o.due,paid:DEMO_DATE,owner:state.role,source:o.id});audit('Obrigação liquidada uma vez '+arg);render();toast('Parcela liquidada somente no simulador.')}return}
if(name==='generate'){const r=state.recurring.find(x=>x.id===arg);if(r){let due=nextMonths('2026-11-01',0,r.day);if(state.obligations.some(o=>o.recurring===r.id&&o.due===due))return toast('A ocorrência da competência já existe.');state.obligations.push({id:uid('PAR'),name:r.name,value:r.value,due,account:r.account,status:'previsto',recurring:r.id});audit('Ocorrência recorrente prevista sem duplicar');render();toast('Competência demonstrativa gerada.')}return}
if(name==='reconcile'){const s=state.stone.find(x=>x.id===arg);if(!s||s.fee===null)return toast('Tarifa pendente: informe taxa manual autorizada.');if(s.credit!==null)return toast('Crédito já registrado: divergência será mantida até análise.');openModal('credit',arg);return}
if(name==='record'){let p=state.patients.find(x=>x.id===arg);if(p)showMessage('Linha do tempo sintética · '+p.name,`<p><b>${esc(p.id)}</b> · uma identidade, múltiplos eventos</p><div class="task"><div class="detail"><b>Cadastro administrativo</b><p>Contatos, representação e dados necessários aos serviços.</p></div></div><div class="task"><div class="detail"><b>Atendimentos</b><p>${state.intakes.filter(i=>i.patient===p.id).length} evento(s) demonstrativos nesta sessão.</p></div></div><div class="task"><div class="detail"><b>Prontuário</b><p>Não implementado: assinaturas, exames e evoluções clínicas válidas permanecem fora do escopo demo.</p></div></div>`);return}
if(name==='new-intake'){state.intakes.push({id:uid('ATD'),patient:arg,professional:'marcia',type:'avulso',date:DEMO_DATE,status:'em espera',notes:'Atendimento avulso fictício'});audit('Atendimento sintético aberto');go('patients','fila');return}
if(name==='intake-next'){let i=state.intakes.find(x=>x.id===arg);if(i){const flow=['em espera','chamado','em atendimento','concluido'];let index=flow.indexOf(i.status);if(index===2&&state.role==='recepcao')return toast('A recepção não conclui ato clínico.');i.status=flow[Math.min(flow.length-1,index+1)];audit('Fluxo operacional '+i.id+' → '+i.status);render();}return}
if(name==='checkin'){let x=state.appointments.find(a=>a.id===arg);if(x){x.status='chegada registrada';if(!state.intakes.some(i=>i.appointment===x.id))state.intakes.push({id:uid('ATD'),appointment:x.id,patient:x.patient,professional:x.professional,date:x.date,type:'agendado',status:'em espera',notes:'Check-in de agenda demonstrativa'});audit('Check-in sem início clínico nem liquidação');render();toast('Check-in registrado em memória.')}return}
if(name==='request-encaixe'){let x=state.appointments.find(a=>a.id===arg);if(x){x.status='solicitacao de encaixe';audit('Encaixe solicitado; depende da profissional');render();toast('Solicitação criada, sem reservar novo horário.')}return}
if(name==='stock-detail'){let x=state.inventory.find(i=>i.id===arg);if(x)showMessage('Histórico do AASI '+x.serial,`<p>${esc(x.model)} · ${esc(x.ownership)}</p>${x.history.map(s=>`<div class="task"><div class="detail">${esc(s)}</div></div>`).join('')}<p class="tiny">Documento, estoque e financeiro têm confirmação própria.</p>`);return}
if(name==='preview-template'){showMessage('Modelo de documento — '+arg,`<p><b>CLÍNICA ÁUDIO S.A. · MODELO FICTÍCIO</b></p><p>Documento de demonstração com campos de paciente, profissional, aparelho e data. Necessita validação jurídica/profissional, assinatura e infraestrutura de guarda antes de uso real.</p>`);return}
if(name==='preview-doc'){const x=state.documents.find(d=>d.id===arg);if(x)showMessage('Prévia não assinada',`<div class="card"><h3>${esc(x.type)}</h3><p>Paciente sintético: ${esc(person(x.patient))}</p><p>Equipamento: ${esc(x.serial)}</p><p>Versão: ${esc(x.version)}</p>${badge(x.status)}<p class="tiny">Documento sem assinatura e sem efeito físico/financeiro.</p></div>`);return}
if(name==='export'){try{if(arg==='xlsx')exportXLSX();else exportPDF();toast('Relatório fictício gerado para download.');}catch(err){console.error(err);toast('Erro na exportação: '+err.message)}return}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;if(el.closest('#active-modal')&&el.dataset.act.startsWith('nav:'))closeModal();if(el.closest('#active-modal')&&el.dataset.act==='modal:notice')closeModal();act(el.dataset.act)});
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;state.draft=null;state.step=1;if(state.app==='finance'&&!safeFinanceAccess())state.page='lancamentos';render();toast('Perfil de interface alterado somente na simulação.');}if(e.target.id==='report-filter'){state.filter=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
// ---- Excel .xlsx real e autocontido: ZIP STORE + Open XML, sem CDN e sem CSV disfarçado. ----
const asBytes=s=>new TextEncoder().encode(s);const xesc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const crcTable=(()=>{let t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
function crc32(data){let crc=0xffffffff;for(let i=0;i<data.length;i++)crc=crcTable[(crc^data[i])&255]^(crc>>>8);return (crc^0xffffffff)>>>0}
function zipStore(entries){let local=[],central=[],offset=0;const u16=n=>[n&255,n>>>8&255],u32=n=>[n&255,n>>>8&255,n>>>16&255,n>>>24&255];for(const [fname,content] of entries){let name=asBytes(fname),data=typeof content==='string'?asBytes(content):content,crc=crc32(data);let header=Uint8Array.from([...u32(0x04034b50),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0)]);local.push(header,name,data);let centralHead=Uint8Array.from([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset)]);central.push(centralHead,name);offset+=header.length+name.length+data.length;}const sizeCentral=central.reduce((s,c)=>s+c.length,0);const end=Uint8Array.from([...u32(0x06054b50),...u16(0),...u16(0),...u16(entries.length),...u16(entries.length),...u32(sizeCentral),...u32(offset),...u16(0)]);return new Blob([...local,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function sheetXML(headers,rows){let all=[headers,...rows.map(r=>headers.map(h=>r[h]??''))];return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="16"/><sheetData>${all.map((row,i)=>`<row r="${i+1}">${row.map((v,j)=>{let col='';let n=j+1;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26)}return `<c r="${col}${i+1}" t="inlineStr"><is><t>${xesc(v)}</t></is></c>`}).join('')}</row>`).join('')}</sheetData></worksheet>`}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportXLSX(){const rows=reportRows(),headers=['data','tipo','descricao','bruto','taxas','liquido','situacao','conta','paciente','profissional'];const entries=[['[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`],['_rels/.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`],['xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Histórico financeiro" sheetId="1" r:id="rId1"/></sheets></workbook>`],['xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`],['xl/worksheets/sheet1.xml',sheetXML(headers,rows)]];download(zipStore(entries),'SGI_Audio_Financeiro_DEMO.xlsx')}
// PDF básico personalizado (download real) apenas texto tabular sintético; impressão gráfica via navegador continua disponível.
function exportPDF(){const rows=reportRows(),report=financialTotals();let lines=[`SGI audiosa.app | Clínica Áudio S.A. | RELATÓRIO DEMONSTRATIVO`,`Data de referência: ${dateBR(DEMO_DATE)} | Origem: dados sintéticos | Não operacional`,`Saldo caixa: ${brl(report.cash)} | A receber: ${brl(report.pendingIncome)} | A pagar: ${brl(report.pendingOut)}`,'','DATA | TIPO | DESCRIÇÃO | LÍQUIDO | SITUAÇÃO',...rows.map(r=>`${r.data} | ${r.tipo} | ${r.descricao} | ${r.liquido} | ${r.situacao}`)];let streams=[];for(let i=0;i<lines.length;i+=40){let part=lines.slice(i,i+40),content=`BT /F1 10 Tf 46 793 Td 15 TL ${part.map((x,j)=>`${j?'T* ':''}(${pdfStr(x.slice(0,108))}) Tj`).join(' ')} ET`;streams.push(content)}let objects=[null,'<< /Type /Catalog /Pages 2 0 R >>',null,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>'];let pids=[];for(const stream of streams){const pageId=objects.length,streamId=objects.length+1;pids.push(pageId);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${streamId} 0 R >>`);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)}objects[2]=`<< /Type /Pages /Kids [${pids.map(i=>i+' 0 R').join(' ')}] /Count ${pids.length} >>`;let raw='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets.push(raw.length);raw+=`${i} 0 obj\n${objects[i]}\nendobj\n`}let start=raw.length;raw+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)raw+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;raw+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)&255);download(new Blob([bytes],{type:'application/pdf'}),'SGI_Audio_Relatorio_DEMO.pdf')}
function pdfStr(s){return String(s).replace(/[\u2010-\u2015]/g,'-').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[^\x20-\xFF]/g,'?').replace(/([\\()])/g,'\\$1')}
render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(err=>console.info('SW não instalado:',err.message));
